import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Map;
import java.util.TreeMap;
import java.util.Set;
import java.util.HashSet;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int L = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());

        String[][] grid = new String[L][C];
        long[] rowSum = new long[L];
        long[] colSum = new long[C];

        Map<String, Long> resolvedValues = new TreeMap<>();
        Set<String> allVariables = new HashSet<>();

        for (int i = 0; i < L; i++) {
            st = new StringTokenizer(reader.readLine());
            for (int j = 0; j < C; j++) {
                grid[i][j] = st.nextToken();
                allVariables.add(grid[i][j]);
            }
            rowSum[i] = Long.parseLong(st.nextToken());
        }

        st = new StringTokenizer(reader.readLine());
        for (int j = 0; j < C; j++) {
            colSum[j] = Long.parseLong(st.nextToken());
        }

        Set<String> unknown = new HashSet<>(allVariables);

        while (!unknown.isEmpty()) {
            boolean found = false;

            // Tenta encontrar em alguma linha
            for (int i = 0; i < L; i++) {
                Set<String> unknownInRow = new HashSet<>();
                for (int j = 0; j < C; j++) {
                    if (unknown.contains(grid[i][j])) {
                        unknownInRow.add(grid[i][j]);
                    }
                }

                if (unknownInRow.size() == 1) {
                    String targetVar = unknownInRow.iterator().next();
                    long knownSum = 0;
                    int countTarget = 0;
                    for (int j = 0; j < C; j++) {
                        if (grid[i][j].equals(targetVar)) {
                            countTarget++;
                        } else {
                            knownSum += resolvedValues.get(grid[i][j]);
                        }
                    }

                    long val = (rowSum[i] - knownSum) / countTarget;
                    resolvedValues.put(targetVar, val);
                    unknown.remove(targetVar);
                    found = true;
                    break;
                }
            }

            if (found) continue;

            // Tenta encontrar em alguma coluna
            for (int j = 0; j < C; j++) {
                Set<String> unknownInCol = new HashSet<>();
                for (int i = 0; i < L; i++) {
                    if (unknown.contains(grid[i][j])) {
                        unknownInCol.add(grid[i][j]);
                    }
                }

                if (unknownInCol.size() == 1) {
                    String targetVar = unknownInCol.iterator().next();
                    long knownSum = 0;
                    int countTarget = 0;
                    for (int i = 0; i < L; i++) {
                        if (grid[i][j].equals(targetVar)) {
                            countTarget++;
                        } else {
                            knownSum += resolvedValues.get(grid[i][j]);
                        }
                    }

                    long val = (colSum[j] - knownSum) / countTarget;
                    resolvedValues.put(targetVar, val);
                    unknown.remove(targetVar);
                    found = true;
                    break;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Long> entry : resolvedValues.entrySet()) {
            sb.append(entry.getKey()).append(" ").append(entry.getValue()).append("\n");
        }
        System.out.print(sb);
    }
}
```

